const hasExternalCheck = !!$env.NDNC_REGISTRY_API_URL;
const externalHit = hasExternalCheck && $input.item.json.on_dnc_registry === true;
return [{ json: { ...$('Postgres - Fetch Callable Leads').item.json, external_dnc_hit: externalHit } }];

// 4.2.1.4: call-list format/export — VICIdial non_agent_api ke liye ready payload banao
const items = $input.all().map(i => i.json);
const callList = items.map(lead => ({
  phone_number: lead.phone,
  lead_id: lead.odoo_lead_id,
  first_name: (lead.name || '').split(' ')[0] || '',
  last_name: (lead.name || '').split(' ').slice(1).join(' ') || '',
  company: lead.company,
  score: lead.score
}));
return [{ json: { call_list: callList, count: callList.length, generated_at: new Date().toISOString() } }];
